cd /tmp/claude-0/ui-mock && cat > shoot.js <<'EOF'
const { chromium } = require('playwright');
const B = 'http://127.0.0.1:8765/';
(async () => {
  const browser = await chromium.launch();
  const scheme = process.argv[2] || 'light';
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 }, colorScheme: scheme });
  const page = await ctx.newPage();
  const errs = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errs.push(m.type() + ': ' + m.text()); });
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('dialog', d => d.accept());
  await page.goto(B + '#run-9');
  await page.waitForSelector('.dfile');
  await page.waitForTimeout(800);
  await page.screenshot({ path: `review-${scheme}.png` });
  console.log('title', await page.title());
  // file jump
  await page.click('[data-jump="1"]'); await page.waitForTimeout(500);
  await page.screenshot({ path: `review-jump-${scheme}.png` });
  // open large file lazily
  await page.click('#dfile-4 > summary'); await page.waitForTimeout(200);
  console.log('large rows', await page.$$eval('#dfile-4 tr', r => r.length));
  // check textarea persistence on waiting run
  await page.keyboard.press('k');
  await page.goto(B + '#run-8'); await page.waitForTimeout(600);
  await page.fill('#q-answer', 'keep the draft');
  await page.waitForTimeout(3500);
  console.log('draft kept', await page.inputValue('#q-answer'));
  await page.screenshot({ path: `waiting-${scheme}.png` });
  // activity tab expand
  await page.click('.ev-text.clamp').catch(()=>{}); await page.waitForTimeout(200);
  await page.screenshot({ path: `activity-${scheme}.png` });
  // j/k
  await page.click('body', {position:{x:5,y:5}}).catch(()=>{});
  await page.keyboard.press('j'); await page.waitForTimeout(400);
  console.log('after j', await page.evaluate(() => location.hash));
  // conflict run
  await page.goto(B + '#run-6'); await page.waitForTimeout(900);
  await page.screenshot({ path: `conflict-${scheme}.png` });
  // dialog
  await page.keyboard.press('n'); await page.waitForTimeout(400);
  await page.fill('#f-repo', '/home/me/proj'); await page.press('#f-repo', 'Tab'); await page.waitForTimeout(400);
  await page.fill('#f-task', 'Add pagination to /api/items');
  await page.screenshot({ path: `dialog-${scheme}.png` });
  console.log('base', await page.inputValue('#f-base'), 'ph', await page.getAttribute('#f-test', 'placeholder'));
  await page.fill('#f-task', 'please fail'); await page.keyboard.press('Control+Enter'); await page.waitForTimeout(400);
  console.log('err', await page.textContent('#f-err'));
  await page.fill('#f-task', 'Add pagination'); await page.keyboard.press('Control+Enter'); await page.waitForTimeout(800);
  console.log('after create', await page.evaluate(() => location.hash), await page.evaluate(() => document.querySelector('#new-dialog').open));
  // connection lost
  await page.route('**/api/**', r => r.abort());
  await page.waitForTimeout(2500);
  console.log('banner visible', await page.isVisible('#conn-banner'));
  await page.screenshot({ path: `disconnected-${scheme}.png` });
  await page.unroute('**/api/**');
  await page.waitForTimeout(3500);
  console.log('banner after', await page.isVisible('#conn-banner'));
  // done section + narrow
  await page.click('#sec-done > summary');
  await page.setViewportSize({ width: 600, height: 900 });
  await page.goto(B + '#run-9'); await page.waitForTimeout(800);
  await page.screenshot({ path: `narrow-${scheme}.png`, fullPage: false });
  const sw = await page.evaluate(() => document.documentElement.scrollWidth);
  console.log('narrow scrollWidth', sw);
  console.log('ERRORS', JSON.stringify(errs.filter(e => !/ERR_FAILED|Failed to load resource/.test(e))));
  console.log('ALL', errs.length);
  await browser.close();
})();
EOF
node shoot.js light

